def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    suitcase_patches = image_patch.find("suitcase")
    roller_patches = image_patch.find("roller")

    if not suitcase_patches or not roller_patches:
        return image_patch

    suitcase_depths = [p.compute_depth() for p in suitcase_patches]
    roller_depths = [p.compute_depth() for p in roller_patches]

    min_suitcase_depth = min(suitcase_depths)
    max_roller_depth = max(roller_depths)

    above = [s for s in suitcase_patches if s.compute_depth() < max_roller_depth]
    below = [r for r in roller_patches if r.compute_depth() > min_suitcase_depth]

    if above and below:
        return above[0]
    elif above:
        return above[0]
    elif below:
        return below[0]
    else:
        return image_patch

